PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (
  email TEXT PRIMARY KEY,
  display_name TEXT,
  role TEXT NOT NULL DEFAULT 'reviewer',
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  last_login TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  CHECK (role IN ('reviewer', 'admin', 'super_admin'))
);
CREATE TABLE user_locations (
  email TEXT NOT NULL,
  location_code TEXT NOT NULL,
  PRIMARY KEY (email, location_code),
  FOREIGN KEY (email) REFERENCES users(email)
);
CREATE TABLE locations (
  location_code TEXT PRIMARY KEY,
  location_pretty TEXT NOT NULL,
  state TEXT,
  gm_name TEXT,
  gm_email TEXT,
  rm_email TEXT,
  incidents_email TEXT,
  ap_email TEXT,
  maintainx_location_id TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, address TEXT, site_number INTEGER);
CREATE TABLE IF NOT EXISTS "claim_photos" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  claim_id TEXT NOT NULL,
  photo_type TEXT NOT NULL,
  filename TEXT NOT NULL,
  r2_key TEXT NOT NULL,
  content_type TEXT,
  size_bytes INTEGER,
  uploaded_at TEXT NOT NULL DEFAULT (datetime('now')),
  uploaded_by TEXT,
  deleted_at TEXT,
  vendor TEXT,
  amount REAL,
  notes TEXT,
  pay_to_type TEXT,
  vendor_address TEXT
);
CREATE TABLE IF NOT EXISTS "claim_activity" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  claim_id TEXT NOT NULL,
  activity_type TEXT NOT NULL,
  status_from TEXT,
  status_to TEXT,
  contact_direction TEXT,
  notes TEXT,
  actor_email TEXT,
  actor_name TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  CHECK (activity_type IN (
    'status_change',
    'note',
    'phone_call',
    'email',
    'contact_attempt',
    'photo_added',
    'document_added',
    'maintainx_created'
  )),
  CHECK (contact_direction IS NULL OR contact_direction IN ('outbound', 'inbound'))
);
CREATE TABLE IF NOT EXISTS "claims" (
  claim_id TEXT PRIMARY KEY,
  location_code TEXT NOT NULL,
  location_pretty TEXT NOT NULL,
  customer_name TEXT NOT NULL,
  customer_phone TEXT,
  customer_email TEXT,
  vehicle_year INTEGER,
  vehicle_make TEXT,
  vehicle_model TEXT,
  vehicle_color TEXT,
  license_plate TEXT,
  damage_description TEXT,
  preexisting_damage TEXT,
  staff_notes TEXT,
  determination TEXT,
  submitted_by TEXT NOT NULL,
  equipment_related INTEGER NOT NULL DEFAULT 0,
  equipment_piece TEXT,
  incident_description TEXT,
  incident_reporter_name TEXT,
  incident_reporter_email TEXT,
  lifecycle_state TEXT NOT NULL DEFAULT 'Open',
  claim_status TEXT NOT NULL DEFAULT 'New — Pending Review',
  status_updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  status_updated_by TEXT,
  site_approval_status TEXT,
  site_approved_at TEXT,
  site_approved_by TEXT,
  contact_owner TEXT,
  contact_status TEXT NOT NULL DEFAULT 'Not Started',
  quote_amount REAL,
  approved_amount REAL,
  payout_method TEXT,
  gm_approved_at TEXT,
  gm_approved_by TEXT,
  rm_approved_at TEXT,
  rm_approved_by TEXT,
  ceo_approved_at TEXT,
  maintainx_priority TEXT,
  maintainx_work_order_id TEXT,
  maintainx_work_order_url TEXT,
  maintainx_created_at TEXT,
  maintainx_created_by TEXT,
  submitted_at TEXT NOT NULL DEFAULT (datetime('now')),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  deleted_at TEXT,
  sharepoint_item_id INTEGER,
  sharepoint_synced_at TEXT,
  customer_mailing_address TEXT,
  ceo_approved_by TEXT,
  approved_quote_id INTEGER,
  parts_ordered TEXT,
  vendor_name TEXT, damage_other TEXT, damage_type TEXT, maintainx_workorder_id INTEGER, idempotency_key TEXT,
  CHECK (lifecycle_state IN ('Open', 'Closed')),
  CHECK (site_approval_status IS NULL OR site_approval_status IN (
    'Pending', 'Approved', 'Denied', 'Escalated to RM'
  )),
  CHECK (contact_owner IS NULL OR contact_owner IN ('GM', 'RM')),
  CHECK (contact_status IN (
    'Not Started',
    'Attempted - Voicemail',
    'Attempted - No Answer',
    'Attempted - Email Sent',
    'Reached',
    'Resolved'
  )),
  CHECK (maintainx_priority IS NULL OR maintainx_priority IN ('HIGH', 'MEDIUM', 'LOW'))
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_locations_site_number ON locations (site_number);
CREATE UNIQUE INDEX idx_claims_idempotency_key ON claims(idempotency_key) WHERE idempotency_key IS NOT NULL;
